const Watch = () => {

/* Watch Page Styles - Premium Anime Streaming */

.watch-page {
  min-height: 100vh;
  background: var(--bg-primary);
  position: relative;
  overflow-x: hidden;
}

/* Background Gradient */
.watch-bg-gradient {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 60vh;
  background: linear-gradient(
    180deg,
    rgba(120, 40, 200, 0.15) 0%,
    rgba(100, 20, 180, 0.1) 30%,
    transparent 100%
  );
  pointer-events: none;
  z-index: 0;
}

/* Main Container */
.watch-container {
  max-width: 1800px;
  margin: 0 auto;
  padding: 0 1.5rem;
  position: relative;
  z-index: 1;
}

/* Video Section */
.video-section {
  padding-top: 6rem;
}

/* Video Container */
.video-container {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #000;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 
    0 25px 80px rgba(0, 0, 0, 0.6),
    0 0 0 1px rgba(255, 255, 255, 0.05);
}

.video-container.theater-mode {
  border-radius: 0;
  max-height: 80vh;
}

/* Video Wrapper */
.video-wrapper {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
}

/* Fake Video Background */
.video-fake-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.video-fake-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.4) saturate(1.2);
}

.video-wrapper::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    transparent 0%,
    rgba(0, 0, 0, 0.3) 100%
  );
  z-index: 1;
  pointer-events: none;
}

/* Loading Spinner */
.video-loading {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  z-index: 10;
}

.loading-spinner {
  width: 60px;
  height: 60px;
  border: 4px solid rgba(255, 255, 255, 0.1);
  border-top-color: var(--accent-primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Play Button Overlay */
.play-overlay {
  position: absolute;
  width: 100px;
  height: 100px;
  background: rgba(139, 92, 246, 0.9);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 5;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
}

.play-overlay svg {
  width: 50px;
  height: 50px;
  color: white;
  margin-left: 5px;
}

.play-overlay:hover {
  transform: scale(1.1);
  background: rgba(139, 92, 246, 1);
  box-shadow: 0 0 40px rgba(139, 92, 246, 0.6);
}

/* Skip Intro Overlay */
.skip-intro-overlay {
  position: absolute;
  bottom: 100px;
  right: 20px;
  z-index: 20;
}

.skip-intro-overlay button {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: rgba(0, 0, 0, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;
  color: white;
  font-size: 0.875rem;
  cursor: pointer;
  transition: all 0.3s ease;
  backdrop-filter: blur(10px);
}

.skip-intro-overlay button:hover {
  background: rgba(139, 92, 246, 0.8);
  border-color: var(--accent-primary);
}

/* Video Controls */
.video-controls {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1rem;
  z-index: 15;
  opacity: 0;
  transform: translateY(10px);
  transition: all 0.3s ease;
}

.video-container.show-controls .video-controls {
  opacity: 1;
  transform: translateY(0);
}

/* Controls Gradient */
.controls-gradient {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 150px;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.8), transparent);
  pointer-events: none;
  z-index: 14;
}

/* Progress Bar */
.progress-container {
  width: 100%;
  padding: 10px 0;
  cursor: pointer;
  position: relative;
  z-index: 16;
}

.progress-bar {
  width: 100%;
  height: 5px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
  overflow: hidden;
  transition: height 0.2s ease;
}

.progress-container:hover .progress-bar {
  height: 8px;
}

.progress-buffered {
  position: absolute;
  height: 5px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 3px;
  transition: height 0.2s ease;
}

.progress-container:hover .progress-buffered {
  height: 8px;
}

.progress-current {
  position: absolute;
  height: 5px;
  background: linear-gradient(90deg, var(--accent-primary), var(--accent-secondary));
  border-radius: 3px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  transition: height 0.2s ease;
}

.progress-container:hover .progress-current {
  height: 8px;
}

.progress-handle {
  width: 14px;
  height: 14px;
  background: white;
  border-radius: 50%;
  transform: translateX(50%) scale(0);
  transition: transform 0.2s ease;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.progress-container:hover .progress-handle {
  transform: translateX(50%) scale(1);
}

/* Controls Row */
.controls-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.75rem;
  position: relative;
  z-index: 16;
}

.controls-left,
.controls-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Control Buttons */
.control-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: white;
  cursor: pointer;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.control-btn svg {
  width: 24px;
  height: 24px;
}

.control-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}

.control-btn.play-btn {
  width: 48px;
  height: 48px;
  background: var(--accent-primary);
  border-radius: 50%;
}

.control-btn.play-btn:hover {
  background: var(--accent-primary);
  transform: scale(1.1);
}

/* Volume Control */
.volume-control {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.volume-slider {
  width: 0;
  opacity: 0;
  transition: all 0.3s ease;
  accent-color: var(--accent-primary);
}

.volume-control:hover .volume-slider {
  width: 80px;
  opacity: 1;
}

/* Time Display */
.time-display {
  color: white;
  font-size: 0.875rem;
  font-weight: 500;
  margin-left: 0.5rem;
  font-variant-numeric: tabular-nums;
}

/* Episode Info Button */
.episode-info-btn {
  padding: 6px 12px;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  border-radius: 6px;
  color: white;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.episode-info-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* Speed Control */
.speed-control {
  position: relative;
}

.speed-btn {
  width: auto;
  padding: 0 12px;
  font-size: 0.875rem;
  font-weight: 600;
}

.speed-menu {
  position: absolute;
  bottom: 100%;
  right: 0;
  background: rgba(20, 20, 20, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 0.5rem;
  backdrop-filter: blur(20px);
  min-width: 100px;
}

.speed-menu button {
  width: 100%;
  padding: 8px 12px;
  background: transparent;
  border: none;
  color: white;
  font-size: 0.875rem;
  text-align: left;
  border-radius: 6px;
  cursor: pointer;
}

.speed-menu button:hover,
.speed-menu button.active {
  background: rgba(139, 92, 246, 0.3);
}

/* Quality Control */
.quality-control {
  position: relative;
}

.quality-btn {
  width: auto;
  padding: 0 12px;
  font-size: 0.875rem;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 6px;
}

.quality-menu {
  position: absolute;
  bottom: 100%;
  right: 0;
  background: rgba(20, 20, 20, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 0.5rem;
  backdrop-filter: blur(20px);
  min-width: 120px;
}

.quality-menu button {
  width: 100%;
  padding: 8px 12px;
  background: transparent;
  border: none;
  color: white;
  font-size: 0.875rem;
  text-align: left;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.quality-menu button:hover,
.quality-menu button.active {
  background: rgba(139, 92, 246, 0.3);
}

.quality-badge {
  font-size: 0.625rem;
  padding: 2px 6px;
  background: var(--accent-primary);
  border-radius: 4px;
  font-weight: 700;
}

/* Episode Navigation */
.episode-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 0;
  margin-top: 1rem;
}

.nav-btn {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem 1.5rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  color: white;
  cursor: pointer;
  transition: all 0.3s ease;
}

.nav-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.15);
  transform: translateX(0);
}

.nav-btn svg {
  width: 24px;
  height: 24px;
}

.nav-info {
  display: flex;
  flex-direction: column;
  text-align: left;
}

.nav-label {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.5);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.nav-title {
  font-size: 0.875rem;
  font-weight: 600;
  margin-top: 4px;
}

.current-episode-badge {
  padding: 0.75rem 1.5rem;
  background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
  border-radius: 30px;
  font-size: 1rem;
  font-weight: 700;
  color: white;
  box-shadow: 0 4px 20px rgba(139, 92, 246, 0.4);
}

/* Anime Info */
.anime-info {
  display: flex;
  gap: 2rem;
  padding: 2rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.info-main {
  flex: 1;
}

.anime-title {
  font-size: 2rem;
  font-weight: 700;
  color: white;
  margin-bottom: 1rem;
  background: linear-gradient(135deg, #fff, rgba(255, 255, 255, 0.8));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.anime-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.meta-item {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.7);
}

.meta-item svg {
  color: #fbbf24;
}

.meta-item.rating {
  color: #fbbf24;
  font-weight: 600;
}

.anime-description {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.6);
  margin-bottom: 1.5rem;
  max-width: 800px;
}

.anime-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.tag {
  padding: 0.5rem 1rem;
  background: rgba(139, 92, 246, 0.15);
  border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: 20px;
  font-size: 0.8125rem;
  color: var(--accent-primary);
  transition: all 0.2s ease;
}

.tag:hover {
  background: rgba(139, 92, 246, 0.25);
  border-color: var(--accent-primary);
}

/* Info Actions */
.info-actions {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-width: 200px;
}

.action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 0.875rem 1.5rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  color: white;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.action-btn svg {
  width: 20px;
  height: 20px;
}

.action-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-2px);
}

.action-btn.primary {
  background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
  border: none;
  box-shadow: 0 4px 20px rgba(139, 92, 246, 0.4);
}

.action-btn.primary:hover {
  box-shadow: 0 6px 30px rgba(139, 92, 246, 0.6);
  transform: translateY(-2px);
}

/* Episodes Sidebar */
.episodes-sidebar {
  position: fixed;
  top: 80px;
  right: 1.5rem;
  width: 380px;
  max-height: calc(100vh - 100px);
  background: rgba(20, 20, 30, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  backdrop-filter: blur(20px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 100;
}

/* Season Selector */
.season-selector {
  padding: 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.season-dropdown-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 1rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  color: white;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.season-dropdown-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.2);
}

.season-dropdown-btn svg {
  width: 20px;
  height: 20px;
}

.season-dropdown {
  position: absolute;
  top: 100%;
  left: 1rem;
  right: 1rem;
  background: rgba(30, 30, 40, 0.98);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 0.5rem;
  backdrop-filter: blur(20px);
  z-index: 10;
}

.season-dropdown button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background: transparent;
  border: none;
  color: white;
  font-size: 0.875rem;
  text-align: left;
  border-radius: 8px;
  cursor: pointer;
}

.season-dropdown button:hover,
.season-dropdown button.active {
  background: rgba(139, 92, 246, 0.2);
}

.episode-count {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.5);
}

/* Episode List */
.episode-list {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
}

.episode-list::-webkit-scrollbar {
  width: 6px;
}

.episode-list::-webkit-scrollbar-track {
  background: transparent;
}

.episode-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

.episode-list::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* Episode Card */
.episode-card {
  display: flex;
  gap: 1rem;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid transparent;
  border-radius: 10px;
  margin-bottom: 0.75rem;
  cursor: pointer;
  transition: all 0.3s ease;
}

.episode-card:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.1);
}

.episode-card.active {
  background: rgba(139, 92, 246, 0.15);
  border-color: var(--accent-primary);
}

.episode-thumbnail {
  position: relative;
  width: 140px;
  height: 80px;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
}

.episode-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.episode-card:hover .episode-thumbnail img {
  transform: scale(1.1);
}

.episode-play-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.4);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.episode-card:hover .episode-play-overlay {
  opacity: 1;
}

.episode-play-overlay svg {
  width: 32px;
  height: 32px;
  color: white;
}

.new-badge {
  position: absolute;
  top: 6px;
  left: 6px;
  padding: 3px 8px;
  background: #ef4444;
  border-radius: 4px;
  font-size: 0.625rem;
  font-weight: 700;
  color: white;
  text-transform: uppercase;
}

.watched-badge {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;
  background: var(--accent-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.watched-badge svg {
  width: 14px;
  height: 14px;
  color: white;
}

.episode-duration {
  position: absolute;
  bottom: 6px;
  right: 6px;
  padding: 2px 6px;
  background: rgba(0, 0, 0, 0.8);
  border-radius: 4px;
  font-size: 0.6875rem;
  font-weight: 600;
  color: white;
}

.episode-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}

.episode-number {
  font-size: 0.75rem;
  color: var(--accent-primary);
  font-weight: 600;
  margin-bottom: 4px;
}

.episode-title {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.9);
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.episode-progress {
  width: 100%;
  height: 3px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  margin-top: 8px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--accent-primary);
  border-radius: 2px;
}

/* Bottom Section */
.bottom-section {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 2rem;
  padding: 2rem 0 4rem;
}

/* Related Section */
.related-section {
  position: sticky;
  top: 100px;
  height: fit-content;
}

.section-title {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 1.125rem;
  font-weight: 700;
  color: white;
  margin-bottom: 1.25rem;
}

.section-title svg {
  width: 22px;
  height: 22px;
  color: var(--accent-primary);
}

.related-grid {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.related-card {
  display: flex;
  gap: 1rem;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.related-card:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.12);
  transform: translateX(5px);
}

.related-card img {
  width: 60px;
  height: 80px;
  border-radius: 8px;
  object-fit: cover;
}

.related-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.related-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: white;
  margin-bottom: 0.5rem;
}

.related-rating {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.8125rem;
  color: #fbbf24;
  font-weight: 600;
}

/* Comments Section */
.comments-section {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 16px;
  padding: 1.5rem;
}

.comments-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}

.comment-count {
  font-size: 0.875rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
  margin-left: 0.5rem;
}

.comments-sort {
  display: flex;
  gap: 0.5rem;
}

.sort-btn {
  padding: 0.5rem 1rem;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.sort-btn:hover {
