.episode-card-new:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.12);
  transform: translateY(-4px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.episode-card-new.active {
  background: rgba(139, 92, 246, 0.1);
  border-color: #8b5cf6;
  box-shadow: 0 0 0 1px rgba(139, 92, 246, 0.3);
}

.ep-thumb {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

.ep-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.episode-card-new:hover .ep-thumb img {
  transform: scale(1.08);
}

.ep-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.3);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.episode-card-new:hover .ep-overlay {
  opacity: 1;
}

.ep-overlay svg {
  width: 50px;
  height: 50px;
  color: white;
}

.ep-badge {
  position: absolute;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
}

.ep-badge.new {
  top: 10px;
  left: 10px;
  background: #ef4444;
  color: white;
}

.ep-badge.watched {
  top: 10px;
  right: 10px;
  width: 28px;
  height: 28px;
  background: #8b5cf6;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.ep-badge.watched svg {
  width: 16px;
  height: 16px;
}

.ep-duration {
  position: absolute;
  bottom: 10px;
  right: 10px;
  padding: 4px 8px;
  background: rgba(0, 0, 0, 0.8);
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 600;
  color: white;
}

.ep-info {
  padding: 1rem;
}

.ep-number {
  display: block;
  font-size: 0.75rem;
  color: #8b5cf6;
  font-weight: 600;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ep-title {
  display: block;
  font-size: 0.9375rem;
  color: rgba(255, 255, 255, 0.9);
  font-weight: 500;
  margin-bottom: 8px;
}

.ep-progress {
  height: 3px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  overflow: hidden;
}

.ep-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #8b5cf6, #a78bfa);
  border-radius: 2px;
}

/* ================================
   COMMENTS SECTION
   ================================ */

.comments-section-new {
  padding: 2rem 0 4rem;
  background: rgba(255, 255, 255, 0.01);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 20px;
  padding: 1.5rem;
}

.comments-header-new {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}

.comment-count {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.5);
  font-weight: 400;
  margin-left: 0.5rem;
}

.sort-btns {
  display: flex;
  gap: 0.5rem;
}

.sort-btn {
  padding: 0.5rem 1rem;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.sort-btn:hover {
  background: rgba(255, 255, 255, 0.05);
  color: white;
}

.sort-btn.active {
  background: #8b5cf6;
  border-color: #8b5cf6;
  color: white;
}

/* Comment Input */
.comment-input-new {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  margin-bottom: 1.5rem;
}

.comment-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  object-fit: cover;
}

.comment-input-new input {
  flex: 1;
  background: transparent;
  border: none;
  color: white;
  font-size: 0.9375rem;
  outline: none;
}

.comment-input-new input::placeholder {
  color: rgba(255, 255, 255, 0.4);
}

.send-btn {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #8b5cf6;
  border: none;
  border-radius: 50%;
  color: white;
  cursor: pointer;
  transition: all 0.2s ease;
}

.send-btn:hover {
  background: #7c3aed;
  transform: scale(1.05);
}

.send-btn svg {
  width: 18px;
  height: 18px;
}

/* Comments List */
.comments-list-new {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.comment-item-new {
  display: flex;
  gap: 1rem;
}

.comment-body {
  flex: 1;
}

.comment-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.5rem;
}

.comment-author {
  font-size: 0.875rem;
  font-weight: 600;
  color: white;
}

.comment-time {
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.4);
}

.comment-text {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 0.75rem;
}

.comment-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.comment-action {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0;
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.5);
  font-size: 0.8125rem;
  cursor: pointer;
  transition: color 0.2s ease;
}

.comment-action:hover {
  color: white;
}

.comment-action svg {
  width: 16px;
  height: 16px;
}

.view-more-btn {
  width: 100%;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  color: #8b5cf6;
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 1.5rem;
}

.view-more-btn:hover {
  background: rgba(139, 92, 246, 0.1);
  border-color: #8b5cf6;
}

/* ================================
   SIDEBAR - RELATED ANIME
   ================================ */

.watch-sidebar {
  position: sticky;
  top: 90px;
  height: fit-content;
  max-height: calc(100vh - 110px);
  overflow-y: auto;
  padding-right: 0.5rem;
}

.watch-sidebar::-webkit-scrollbar {
  width: 4px;
}

.watch-sidebar::-webkit-scrollbar-track {
  background: transparent;
}

.watch-sidebar::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
}

.sidebar-title {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 1.125rem;
  font-weight: 700;
  color: white;
  margin-bottom: 1.25rem;
}

.sidebar-title svg {
  width: 22px;
  height: 22px;
  color: #8b5cf6;
}

.related-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.related-card-new {
  display: flex;
  gap: 1rem;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 14px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.related-card-new:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
  transform: translateX(5px);
}

.related-card-new img {
  width: 70px;
  height: 95px;
  border-radius: 10px;
  object-fit: cover;
}

.related-info {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.5rem;
}

.related-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: white;
}

.related-rating {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.8125rem;
  color: #fbbf24;
  font-weight: 600;
}

.related-rating svg {
  width: 14px;
  height: 14px;
}

/* ================================
   MINI PLAYER
   ================================ */

.mini-player-new {
  position: fixed;
  bottom: 1.5rem;
  left: 1.5rem;
  right: 1.5rem;
  max-width: 450px;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.75rem 1rem;
  background: rgba(20, 20, 30, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  backdrop-filter: blur(20px);
  box-shadow: 0 10px 50px rgba(0, 0, 0, 0.6);
  z-index: 1000;
}

.mini-thumb {
  width: 100px;
  height: 56px;
  border-radius: 8px;
  object-fit: cover;
}

.mini-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mini-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: white;
}

.mini-ep {
  font-size: 0.8125rem;
  color: rgba(255, 255, 255, 0.5);
}

.mini-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.mini-btn {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: white;
  cursor: pointer;
  border-radius: 10px;
  transition: all 0.2s ease;
}

.mini-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}

.mini-btn svg {
  width: 22px;
  height: 22px;
}

.mini-btn:first-child {
  background: #8b5cf6;
  border-radius: 50%;
}

.mini-btn:first-child:hover {
  background: #7c3aed;
}

.mini-btn.close:hover {
  background: rgba(239, 68, 68, 0.3);
  color: #ef4444;
}

/* ================================
   RESPONSIVE
   ================================ */

@media (max-width: 1200px) {
  .watch-container {
    grid-template-columns: 1fr;
  }

  .watch-sidebar {
    position: relative;
    top: 0;
    max-height: none;
  }

  .related-list {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 1rem;
  }

  .related-card-new {
    flex-shrink: 0;
    width: 160px;
    flex-direction: column;
  }

  .related-card-new img {
    width: 100%;
    height: 90px;
  }
}

@media (max-width: 768px) {
  .watch-container {
    padding: 0 1rem;
  }

  .anime-info-new {
    flex-direction: column;
    gap: 1.5rem;
  }

  .anime-actions {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .anime-title-new {
    font-size: 1.5rem;
  }

  .anime-meta-new {
    gap: 0.5rem;
  }

  .meta-badge {
    padding: 0.375rem 0.75rem;
    font-size: 0.75rem;
  }

  .episode-nav-new {
    flex-direction: column;
    gap: 0.75rem;
  }

  .nav-btn-new {
    width: 100%;
    max-width: none;
  }

  .episodes-grid {
    grid-template-columns: 1fr;
  }

  .mini-player-new {
    left: 1rem;
    right: 1rem;
    bottom: 1rem;
  }
}

@media (max-width: 480px) {
  .video-container-new {
    border-radius: 0;
    margin: 0 -1rem;
    width: calc(100% + 2rem);
  }

  .controls-bar {
    padding: 0 0.75rem 0.75rem;
  }

  .ctrl-btn {
    width: 36px;
    height: 36px;
  }

  .ctrl-btn svg {
    width: 20px;
    height: 20px;
  }

  .time-label {
    font-size: 0.75rem;
  }

  .episode-badge {
    display: none;
  }
}

