    bottom: 1rem;
    max-width: none;
  }

  .comments-section-new {
    padding: 1.5rem;
  }
}

@media (max-width: 480px) {
  .video-container-new {
    border-radius: 0;
    margin: -0.5rem -1rem 1.5rem;
    width: calc(100% + 2rem);
  }

  .controls-bar {
    padding: 0 0.75rem 0.75rem;
  }

  .ctrl-btn {
    width: 38px;
    height: 38px;
  }

  .ctrl-btn svg {
    width: 20px;
    height: 20px;
  }

  .time-label {
    font-size: 0.75rem;
  }

  .episode-badge {
    display: none;
  }

  .anime-title-new {
    font-size: 1.5rem;
  }

  .anime-genres {
    gap: 0.5rem;
  }

  .genre-tag {
    padding: 0.375rem 1rem;
    font-size: 0.8125rem;
  }
}

