import React, { useState, useRef, useEffect } from 'react';
import { motion } from 'framer-motion';
import './Watch.css';

// Sample data - Anime info
const animeData = {
  title: "Demon Slayer: Kimetsu no Yaiba",
  originalTitle: "鬼滅の刃",
  rating: 9.2,
  year: 2019,
  type: "TV",
  episodes: 55,
  status: "Finished",
  ageRating: "R - 17+",
  duration: "24 min",
  studios: "ufotable",
  genres: ["Action", "Fantasy", "Supernatural"]
};

const seasons = [
  { id: 1, name: "Season 1", episodes: 26, year: "2019" },
  { id: 2, name: "Season 2 - Mugen Train", episodes: 7, year: "2021" },
  { id: 3, name: "Season 3 - Entertainment District", episodes: 11, year: "2022" },
  { id: 4, name: "Season 4 - Swordsmith Village", episodes: 11, year: "2023" },
];

// Generate episodes
const allEpisodes = [];
for (let season = 1; season <= 4; season++) {
  const epCount = season === 1 ? 26 : season === 2 ? 7 : 11;
  for (let i = 1; i <= epCount; i++) {
    allEpisodes.push({
      id: `${season}-${i}`,
      season,
      number: i,
      title: `Episode ${i}`,
      duration: "24:15",
      isNew: season === 4 && i === 11,
      isWatched: season === 1 && i < 5,
      progress: season === 1 && i === 3 ? 65 : 0,
    });
  }
}

const relatedAnime = [
  { id: 1, title: "Attack on Titan", rating: 9.1 },
  { id: 2, title: "Jujutsu Kaisen", rating: 8.9 },
  { id: 3, title: "Chainsaw Man", rating: 8.7 },
  { id: 4, title: "Spy x Family", rating: 8.8 },
  { id: 5, title: "My Hero Academia", rating: 8.4 },
];

const comments = [
  { id: 1, user: "AnimeMaster99", avatar: "👤", text: "This animation is absolutely stunning! The fight scenes are so well choreographed.", time: "2 hours ago", likes: 234 },
  { id: 2, user: "DemonSlayer_Fan", avatar: "⚔️", text: "Best anime of 2023! Can't wait for the next season.", time: "5 hours ago", likes: 189 },
  { id: 3, user: "OTAKU_King", avatar: "🎭", text: "Tanjiro's character development is phenomenal. Every episode keeps getting better!", time: "1 day ago", likes: 156 },
];

const Watch = () => {
  const [currentEpisode, setCurrentEpisode] = useState({ season: 1, number: 1 });
  const [showControls, setShowControls] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const [selectedSeason, setSelectedSeason] = useState(1);
  const [showSeasonDropdown, setShowSeasonDropdown] = useState(false);
  const [showSpeedMenu, setShowSpeedMenu] = useState(false);
  const [showQualityMenu, setShowQualityMenu] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showMiniPlayer, setShowMiniPlayer] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);

  const videoRef = useRef(null);
  const containerRef = useRef(null);
  const hideTimeout = useRef(null);

  // Get current episode data
  const currentEpData = allEpisodes.find(
    ep => ep.season === currentEpisode.season && ep.number === currentEpisode.number
  );

  // Filter episodes by selected season
  const seasonEpisodes = allEpisodes.filter(ep => ep.season === selectedSeason);

  // Navigation
  const hasPrev = currentEpisode.season > 1 || currentEpisode.number > 1;
  const hasNext = currentEpisode.season < 4 || currentEpisode.number < 21;

  const goToPrev = () => {
    if (currentEpisode.number > 1) {
      setCurrentEpisode({ ...currentEpisode, number: currentEpisode.number - 1 });
    } else if (currentEpisode.season > 1) {
      const newSeason = currentEpisode.season - 1;
      const newEpCount = newSeason === 1 ? 26 : newSeason === 2 ? 7 : 11;
      setCurrentEpisode({ season: newSeason, number: newEpCount });
    }
  };

  const goToNext = () => {
    const maxEp = currentEpisode.season === 1 ? 26 : currentEpisode.season === 2 ? 7 : 11;
    if (currentEpisode.number < maxEp) {
      setCurrentEpisode({ ...currentEpisode, number: currentEpisode.number + 1 });
    } else if (currentEpisode.season < 4) {
      setCurrentEpisode({ season: currentEpisode.season + 1, number: 1 });
    }
  };

  // Video controls
  const togglePlay = () => setIsPlaying(!isPlaying);

  const handleMouseMove = () => {
    setShowControls(true);
    if (hideTimeout.current) clearTimeout(hideTimeout.current);
    hideTimeout.current = setTimeout(() => {
      if (isPlaying) setShowControls(false);
    }, 3000);
  };

  const handleProgressClick = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const newProgress = ((e.clientX - rect.left) / rect.width) * 100;
    setProgress(Math.min(100, Math.max(0, newProgress)));
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  // Format time
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Episode thumbnail placeholder
  const getEpisodeThumbnail = (season, ep) => {
    const colors = ['1a1a2e', '16213e', '0f3460', '1a1a2e'];
    return colors[(season + ep) % 4];
  };

  return (
    <div className="watch-page">
      <div className="watch-ambient-bg" />

      <div className="watch-container">
        {/* Main Content */}
        <div className="watch-main">
          {/* Video Player */}
          <motion.div 
            className={`video-container-new ${showControls ? 'show-controls' : ''}`}
            ref={containerRef}
            onMouseMove={handleMouseMove}
            onMouseLeave={() => isPlaying && setShowControls(false)}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            {/* Video Background */}
            <div className="video-bg">
              <div 
                className="video-bg-placeholder"
                style={{ 
                  background: `linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)` 
                }}
              >
                <div className="placeholder-icon">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M8 5v14l11-7z"/>
                  </svg>
                </div>
              </div>
            </div>

            {/* Loading */}
            {!imageLoaded && (
              <div className="video-loading">
                <div className="spinner" />
              </div>
            )}

            {/* Play Button */}
            {!isPlaying && (
              <motion.button 
                className="play-button"
                onClick={togglePlay}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
              >
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M8 5v14l11-7z"/>
                </svg>
              </motion.button>
            )}

            {/* Video Overlay */}
            <div className="video-overlay" />

            {/* Controls */}
            <div className="video-controls-new">
              <div className="controls-gradient-new" />

              {/* Progress Bar */}
              <div className="progress-area" onClick={handleProgressClick}>
                <div className="progress-track">
                  <div 
                    className="progress-fill-new" 
                    style={{ width: `${progress}%` }}
                  />
                  <div 
                    className="progress-thumb" 
                    style={{ left: `${progress}%` }}
                  />
                </div>
              </div>

              {/* Controls Bar */}
              <div className="controls-bar">
                <div className="controls-left">
                  <button className="ctrl-btn play-btn" onClick={togglePlay}>
                    {isPlaying ? (
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M6 4h4v16H6V4zm8 0h4v16h-4V4z"/>
                      </svg>
                    ) : (
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M8 5v14l11-7z"/>
                      </svg>
                    )}
                  </button>

                  <button className="ctrl-btn" onClick={goToPrev} disabled={!hasPrev}>
                    <svg viewBox="0 0 24 24" fill="currentColor">
                      <path d="M6 6h2v12H6V6zm3.5 6l8.5 6V6l-8.5 6z"/>
                    </svg>
                  </button>

                  <button className="ctrl-btn" onClick={goToNext} disabled={!hasNext}>
                    <svg viewBox="0 0 24 24" fill="currentColor">
                      <path d="M6 18l8.5-6L6 6v12zm10-12v12h2V6h-2z"/>
                    </svg>
                  </button>

                  <div className="volume-group">
                    <button className="ctrl-btn">
                      {volume === 0 ? (
                        <svg viewBox="0 0 24 24" fill="currentColor">
                          <path d="M16.5 12c0-1.77-1.02-3.29-2.5-4.03v2.21l2.45 2.45c.03-.2.05-.41.05-.63zm2.5 0c0 .94-.2 1.82-.54 2.64l1.51 1.51C20.63 14.91 21 13.5 21 12c0-4.28-2.99-7.86-7-8.77v2.06c2.89.86 5 3.54 5 6.71zM4.27 3L3 4.27 7.73 9H3v6h4l5 5v-6.73l4.25 4.25c-.67.52-1.42.93-2.25 1.18v2.06c1.38-.31 2.63-.95 3.69-1.81L19.73 21 21 19.73l-9-9L4.27 3zM12 4L9.91 6.09 12 8.18V4z"/>
                        </svg>
                      ) : (
                        <svg viewBox="0 0 24 24" fill="currentColor">
                          <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
                        </svg>
                      )}
                    </button>
                    <input 
                      type="range" 
                      min="0" 
                      max="1" 
                      step="0.1"
                      value={volume}
                      onChange={(e) => setVolume(parseFloat(e.target.value))}
                      className="volume-slider-new"
                    />
                  </div>

                  <span className="time-label">
                    {formatTime(progress * 2.4)} / {formatTime(1440)}
                  </span>
                </div>

                <div className="controls-right">
                  <span className="episode-badge">
                    S{currentEpisode.season} E{currentEpisode.number}
                  </span>

                  {/* Speed */}
                  <div className="dropdown-wrapper">
                    <button 
                      className="ctrl-btn dropdown-trigger"
                      onClick={() => {
                        setShowSpeedMenu(!showSpeedMenu);
                        setShowQualityMenu(false);
                      }}
                    >
                      1x
                    </button>
                    {showSpeedMenu && (
                      <div className="dropdown-menu">
                        {['0.5x', '0.75x', '1x', '1.25x', '1.5x', '2x'].map(speed => (
                          <button key={speed} className={speed === '1x' ? 'active' : ''}>
                            {speed}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Quality */}
                  <div className="dropdown-wrapper">
                    <button 
                      className="ctrl-btn dropdown-trigger"
                      onClick={() => {
                        setShowQualityMenu(!showQualityMenu);
                        setShowSpeedMenu(false);
                      }}
                    >
                      <svg viewBox="0 0 24 24" fill="currentColor" style={{width: 20, height: 20}}>
                        <path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14c0 3.31 2.69 6 6 6h13c2.76 0 5-2.24 5-5 0-2.64-2.05-4.78-4.65-4.96z"/>
                      </svg>
                    </button>
                    {showQualityMenu && (
                      <div className="dropdown-menu">
                        {['4K', '1080p', '720p', '480p', '360p'].map(quality => (
                          <button key={quality} className={quality === '1080p' ? 'active' : ''}>
                            {quality} {quality === '1080p' && <span style={{fontSize: '0.625rem'}}>BEST</span>}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Fullscreen */}
                  <button className="ctrl-btn" onClick={toggleFullscreen}>
                    {isFullscreen ? (
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M5 16h3v3h2v-5H5v2zm3-8H5v2h5V5H8v3zm6 11h2v-3h3v-2h-5v5zm2-11V5h-2v5h5V8h-3z"/>
                      </svg>
                    ) : (
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M7 14H5v5h5v-2H7v-3zm-2-4h2V7h3V5H5v5zm12 7h-3v2h5v-5h-2v3zM14 5v2h3v3h2V5h-5z"/>
                      </svg>
                    )}
                  </button>
                </div>
              </div>
            </div>
          </motion.div>

          {/* Episode Navigation */}
          <motion.div 
            className="episode-nav-new"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
          >
            <button className="nav-btn-new" onClick={goToPrev} disabled={!hasPrev}>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"/>
              </svg>
              <div className="nav-text">
                <span className="nav-label">Previous</span>
                <span className="nav-title">
                  S{Math.max(1, currentEpisode.season - (currentEpisode.number === 1 ? 1 : 0))} E{Math.max(1, currentEpisode.number - 1) || (currentEpisode.number === 1 ? 26 : 11)}
                </span>
              </div>
            </button>

            <div className="current-ep-badge">
              S{currentEpisode.season} • E{currentEpisode.number}
            </div>

            <button className="nav-btn-new next" onClick={goToNext} disabled={!hasNext}>
              <div className="nav-text">
                <span className="nav-label">Next</span>
                <span className="nav-title">
                  S{currentEpisode.number === 26 ? Math.min(4, currentEpisode.season + 1) : currentEpisode.season} E{currentEpisode.number === 26 ? 1 : currentEpisode.number + 1}
                </span>
              </div>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/>
              </svg>
            </button>
          </motion.div>

          {/* Anime Info */}
          <motion.div 
            className="anime-info-new"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            <div className="anime-info-main">
              <h1 className="anime-title-new">{animeData.title}</h1>

              <div className="anime-meta-new">
                <div className="meta-badge rating">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/>
                  </svg>
                  {animeData.rating}
                </div>
                <div className="meta-badge">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M19 3h-1V1h-2v2H8V1H6v2H5c-1.11 0-1.99.9-1.99 2L3 19c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 16H5V8h14v11zM9 10H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2zm-8 4H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2z"/>
                  </svg>
                  {animeData.year}
                </div>
                <div className="meta-badge">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M18 4l2 4h-3l-2-4h-2l2 4h-3l-2-4H8l2 4H7L5 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V4h-4z"/>
                  </svg>
                  {animeData.type}
                </div>
                <div className="meta-badge">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z"/>
                  </svg>
                  {animeData.duration}
                </div>
                <div className="meta-badge">
                  {animeData.ageRating}
                </div>
              </div>

              <p className="anime-desc-new">
                Tanjiro Kamado, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. The sole survivor is his sister Nezuko, who has been transformed into a demon. To avenge his family and cure his sister, Tanjiro begins rigid training to become a demon slayer.
              </p>

              <div className="anime-genres">
                {animeData.genres.map((genre, idx) => (
                  <span key={idx} className="genre-tag">{genre}</span>
                ))}
              </div>
            </div>

            <div className="anime-actions">
              <button className="action-btn-new primary">
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/>
                </svg>
                Add to List
              </button>
              <button className="action-btn-new">
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11c.54.5 1.25.81 2.04.81 1.66 0 3-1.34 3-3s-1.34-3-3-3-3 1.34-3 3c0 .24.04.47.09.7L8.04 9.81C7.5 9.31 6.79 9 6 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c.79 0 1.5-.31 2.04-.81l7.12 4.16c-.05.21-.08.43-.08.65 0 1.61 1.31 2.92 2.92 2.92s2.92-1.31 2.92-2.92-1.31-2.92-2.92-2.92z"/>
                </svg>
                Share
              </button>
              <button className="action-btn-new">
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                </svg>
                Like
              </button>
            </div>
          </motion.div>

          {/* Episodes Section */}
          <motion.section 
            className="episodes-section"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.3 }}
          >
            <div className="section-header">
              <h2 className="section-title-new">
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M4 6H2v14c0 1.1.9 2 2 2h14v-2H4V6zm16-4H8c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-8 12.5v-9l6 4.5-6 4.5z"/>
                </svg>
                Episodes
              </h2>

              <div className="season-select-wrapper">
                <button 
                  className="season-select-btn"
                  onClick={() => setShowSeasonDropdown(!showSeasonDropdown)}
                >
                  {seasons.find(s => s.id === selectedSeason)?.name}
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M7 10l5 5 5-5z"/>
                  </svg>
                </button>

                {showSeasonDropdown && (
                  <div className="season-dropdown-new">
                    {seasons.map(season => (
                      <button 
                        key={season.id}
                        className={season.id === selectedSeason ? 'active' : ''}
                        onClick={() => {
                          setSelectedSeason(season.id);
                          setShowSeasonDropdown(false);
                        }}
                      >
                        {season.name}
                        <span>{season.episodes} eps</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>

            <div className="episodes-grid">
              {seasonEpisodes.map((ep) => (
                <motion.div
                  key={ep.id}
                  className={`episode-card-new ${
                    ep.season === currentEpisode.season && 
                    ep.number === currentEpisode.number ? 'active' : ''
                  }`}
                  onClick={() => setCurrentEpisode({ season: ep.season, number: ep.number })}
                  whileHover={{ y: -6 }}
                  transition={{ duration: 0.3 }}
                >
                  <div className="ep-thumb">
                    <div 
                      className="ep-thumb-placeholder"
                      style={{
                        background: `linear-gradient(135deg, #${getEpisodeThumbnail(ep.season, ep.number)} 0%, #16213e 100%)`
                      }}
                    >
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M21 3H3c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 16H3V5h18v14zM9 8l7 4-7 4V8z"/>
                      </svg>
                    </div>

                    <div className="ep-overlay">
                      <svg viewBox="0 0 24 24" fill="currentColor">
                        <path d="M8 5v14l11-7z"/>
                      </svg>
                    </div>

                    {ep.isNew && <span className="ep-badge new">NEW</span>}

                    {ep.isWatched && (
                      <span className="ep-badge watched">
                        <svg viewBox="0 0 24 24" fill="currentColor">
                          <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>
                        </svg>
                      </span>
                    )}

                    <span className="ep-duration">{ep.duration}</span>
                  </div>

                  <div className="ep-info">
                    <span className="ep-number">Episode {ep.number}</span>
                    <span className="ep-title">{ep.title}</span>

                    {ep.progress > 0 && (
                      <div className="ep-progress">
                        <div className="ep-progress-fill" style={{ width: `${ep.progress}%` }} />
                      </div>
                    )}
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.section>

          {/* Comments Section */}
          <motion.section 
            className="comments-section-new"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.4 }}
          >
            <div className="comments-header-new">
              <h2 className="section-title-new">
                Comments
                <span className="comment-count">({comments.length})</span>
              </h2>

              <div className="sort-btns">
                <button className="sort-btn active">Top</button>
                <button className="sort-btn">Newest</button>
              </div>
            </div>

            {/* Comment Input */}
            <div className="comment-input-new">
              <div className="comment-avatar" style={{background: 'linear-gradient(135deg, #8b5cf6, #a78bfa)'}}>
                👤
              </div>
              <input type="text" placeholder="Share your thoughts about this anime..." />
              <button className="send-btn">
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
                </svg>
              </button>
            </div>

            {/* Comments List */}
            <div className="comments-list-new">
              {comments.map((comment) => (
                <div key={comment.id} className="comment-item-new">
                  <div className="comment-avatar" style={{background: 'linear-gradient(135deg, #374151, #1f2937)'}}>
                    {comment.avatar}
                  </div>
                  <div className="comment-body">
                    <div className="comment-meta">
                      <span className="comment-author">{comment.user}</span>
                      <span className="comment-time">{comment.time}</span>
                    </div>
                    <p className="comment-text">{comment.text}</p>
                    <div className="comment-actions">
                      <button className="comment-action">
                        <svg viewBox="0 0 24 24" fill="currentColor">
                          <path d="M1 21h4V9H1v12zm22-11c0-1.1-.9-2-2-2h-6.31l.95-4.57.03-.32c0-.41-.17-.79-.44-1.06L14.17 1 7.59 7.59C7.22 7.95 7 8.45 7 9v10c0 1.1.9 2 2 2h9c.83 0 1.54-.5 1.84-1.22l3.02-7.05c.09-.23.14-.47.14-.73v-2z"/>
                        </svg>
                        {comment.likes}
                      </button>
                      <button className="comment-action">Reply</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <button className="view-more-btn">View All Comments</button>
          </motion.section>
        </div>

        {/* Sidebar - Related Anime */}
        <motion.aside 
          className="watch-sidebar"
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          <h3 className="sidebar-title">
            <svg viewBox="0 0 24 24" fill="currentColor">
              <path d="M4 8h4V4H4v4zm6 12h4v-4h-4v4zm-6 0h4v-4H4v4zm0-6h4v-4H4v4zm6 0h4v-4h-4v4zm6-10v4h4V4h-4zm-6 4h4V4h-4v4zm6 6h4v-4h-4v4zm0 6h4v-4h-4v4z"/>
            </svg>
            Related Anime
          </h3>

          <div className="related-list">
            {relatedAnime.map((anime) => (
              <motion.div 
                key={anime.id} 
                className="related-card-new"
                whileHover={{ x: 5 }}
                transition={{ duration: 0.2 }}
              >
                <div 
                  style={{
                    width: '75px',
                    height: '100px',
                    borderRadius: '10px',
                    background: 'linear-gradient(135deg, #1a1a2e, #16213e)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}
                >
                  <svg viewBox="0 0 24 24" fill="rgba(139, 92, 246, 0.3)" style={{width: 30, height: 30}}>
                    <path d="M18 4l2 4h-3l-2-4h-2l2 4h-3l-2-4H8l2 4H7L5 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V4h-4z"/>
                  </svg>
                </div>
                <div className="related-info">
                  <span className="related-title">{anime.title}</span>
                  <span className="related-rating">
                    <svg viewBox="0 0 24 24" fill="currentColor">
                      <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/>
                    </svg>
                    {anime.rating}
                  </span>
                </div>
              </motion.div>
            ))}
          </div>
        </motion.aside>
      </div>

      {/* Mini Player */}
      {showMiniPlayer && (
        <motion.div 
          className="mini-player-new"
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
        >
          <div className="mini-thumb">
            <svg viewBox="0 0 24 24" fill="rgba(139, 92, 246, 0.4)">
              <path d="M8 5v14l11-7z"/>
            </svg>
          </div>
          <div className="mini-info">
            <span className="mini-title">{animeData.title}</span>
            <span className="mini-ep">S{currentEpisode.season} E{currentEpisode.number}</span>
          </div>
          <div className="mini-controls">
            <button className="mini-btn play-mini" onClick={togglePlay}>
              {isPlaying ? (
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M6 4h4v16H6V4zm8 0h4v16h-4V4z"/>
                </svg>
              ) : (
                <svg viewBox="0 0 24 24" fill="currentColor">
                  <path d="M8 5v14l11-7z"/>
                </svg>
              )}
            </button>
            <button className="mini-btn close" onClick={() => setShowMiniPlayer(false)}>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/>
              </svg>
            </button>
          </div>
        </motion.div>
      )}
    </div>
  );
};

export default Watch;
